177: /**
178:  * Item-state precedence. A reference contradicting the declared scope is worse
179:  * than one that is merely unknown, and an unknown reference needs a creation
180:  * decision where an ambiguous one needs only a selection.
181:  */
182: const STATE_PRECEDENCE: Record<ReferenceResolutionState, number> = {
183:   resolved: 0,
184:   ambiguous: 1,
185:   unresolved: 2,
186:   invalid: 3,
