189: function worstState(states: ReferenceResolutionState[]): ReferenceResolutionState {
190:   return states.reduce<ReferenceResolutionState>(
191:     (worst, state) => (STATE_PRECEDENCE[state] > STATE_PRECEDENCE[worst] ? state : worst),
192:     'resolved',
