196: /**
197:  * Split `namespace:entityType:value`. The contract already constrains the shape;
198:  * this reads it without re-validating and returns null for anything it cannot
199:  * split, so that a caller stages rather than assumes.
200:  */
201: function parseSourceIdentifier(value: string): SourceIdentifier | null {
202:   const firstSeparator = value.indexOf(':');
203:   if (firstSeparator < 1) {
204:     return null;
205:   }
206: 
207:   const secondSeparator = value.indexOf(':', firstSeparator + 1);
208:   if (secondSeparator < firstSeparator + 2) {
209:     return null;
210:   }
211: 
212:   const remainder = value.slice(secondSeparator + 1);
213:   if (remainder.length === 0) {
214:     return null;
215:   }
216: 
217:   return {
218:     namespace: value.slice(0, firstSeparator),
219:     entityType: value.slice(firstSeparator + 1, secondSeparator),
220:     value: remainder,
221:   };
