238:     entityType,
239:     state,
240:     submittedReference,
241:     canonicalId: detail.canonicalId ?? null,
242:     matchedBy: detail.matchedBy ?? null,
243:     candidates: detail.candidates ?? [],
244:     reason: detail.reason ?? null,
245:   };
246: }
