248: /**
249:  * Applies a reviewer's recorded reference mapping.
250:  *
251:  * A mapping normally selects one of the candidates this reference itself
252:  * offered, and the candidate check is what stops a mapping being applied after
253:  * the batch has moved on beneath it.
254:  *
255:  * `admissible` widens that for the one case where the check cannot be met:
256:  * participant onboarding. A task exists precisely because the resolver could
257:  * offer nothing â€” an identifier naming nobody offers no candidate at all â€” so
258:  * a decision settling one could never be applied, and the batch stayed
259:  * unapprovable however many tasks the reviewer settled. Where a caller can
260:  * name the canonical records the reference is allowed to resolve to (for a
261:  * participant, the resolved fixture's own squad), a mapping onto one of those
262:  * is honoured. It is not a widening of matching: the person is there because a
263:  * reviewer put them in that squad by the decision this mapping records.
264:  */
265: function applyOverride(
266:   value: ReferenceOutcome,
267:   overrides: ReadonlyMap<string, ReferenceResolutionOverride>,
268:   admissible?: ReadonlyMap<string, string>,
269: ): ReferenceOutcome {
270:   const override = overrides.get(value.referencePath);
271:   if (!override || value.state === 'resolved' || override.entityType !== value.entityType)
272:     return value;
273:   const selected = value.candidates.find(
274:     (candidate) => candidate.canonicalId === override.canonicalId && !candidate.outOfScope,
275:   );
276:   const label = selected?.label ?? admissible?.get(override.canonicalId);
277:   return label === undefined
278:     ? value
279:     : {
280:         ...value,
281:         state: 'resolved',
282:         canonicalId: override.canonicalId,
283:         matchedBy: 'manual',
284:         reason: `Mapped to ${label} by an authorised user.`,
285:       };
286: }
