288: /** Reduce an outcome to the provenance recorded against a staged item. */
289: function provenance(value: ReferenceOutcome): Record<string, unknown> {
290:   return {
291:     referencePath: value.referencePath,
292:     entityType: value.entityType,
293:     state: value.state,
294:     submittedReference: value.submittedReference,
295:     canonicalId: value.canonicalId,
296:     matchedBy: value.matchedBy,
297:     candidates: value.candidates,
298:     reason: value.reason,
299:   };
