 316: function groupBy<Row, Key>(rows: Row[], key: (row: Row) => Key): Map<Key, Row[]> {
 317:   const grouped = new Map<Key, Row[]>();
 318: 
 319:   for (const row of rows) {
 320:     const rowKey = key(row);
 321:     const existing = grouped.get(rowKey);
 322: 
 323:     if (existing) {
 324:       existing.push(row);
 325:     } else {
 326:       grouped.set(rowKey, [row]);
 327:     }
 328:   }
 329: 
 330:   return grouped;
 331: }
