 394: function resolveNamedReference(
 395:   referencePath: string,
 396:   entityType: ReferenceEntityType,
 397:   reference: ReferenceInput,
 398:   name: string | null,
 399:   rowsByName: Map<string, NamedRow[]>,
 400:   supportedKey: string,
 401: ): ReferenceOutcome {
 402:   const submitted = { sourceId: reference.sourceId, context: reference.context };
 403: 
 404:   // A source identifier can never resolve this entity type, because no
 405:   // source-reference column exists to compare against and #360 adds none. That
 406:   // is a different situation from a reference that simply was not found this
 407:   // time, so it is reported as such rather than left to read as absence.
 408:   if (reference.sourceId && !name) {
 409:     return outcome(referencePath, entityType, submitted, 'unresolved', {
 410:       reason: unsupportedSourceIdentifier(entityType, supportedKey),
 411:     });
 412:   }
 413: 
 414:   if (!name) {
 415:     return outcome(referencePath, entityType, submitted, 'invalid', {
 416:       reason: 'The reference carries neither a source identifier nor a readable name.',
 417:     });
 418:   }
 419: 
 420:   // Where the reference carries both, the name is the supported key and is
 421:   // used. The ignored identifier is still recorded, so the submitter learns the
 422:   // field had no effect.
 423:   const ignoredNote = reference.sourceId ? ignoredSourceIdentifier(entityType, supportedKey) : null;
 424: 
 425:   const matches = rowsByName.get(name) ?? [];
 426: 
 427:   if (matches.length === 1) {
 428:     return outcome(referencePath, entityType, submitted, 'resolved', {
 429:       canonicalId: matches[0]!.canonicalId,
 430:       matchedBy: 'exact-name',
 431:       reason: ignoredNote,
 432:     });
 433:   }
 434: 
 435:   if (matches.length > 1) {
 436:     return outcome(referencePath, entityType, submitted, 'ambiguous', {
 437:       candidates: matches.map((row) => ({ canonicalId: row.canonicalId, label: row.name })),
 438:       reason: withNote(
 439:         ignoredNote,
 440:         `The name "${name}" matches ${String(matches.length)} records. A name is not treated as unique, so the choice is left to review.`,
 441:       ),
 442:     });
 443:   }
 444: 
 445:   return outcome(referencePath, entityType, submitted, 'unresolved', {
 446:     reason: withNote(ignoredNote, `No record has the exact name "${name}".`),
 447:   });
 448: }
