496:     });
497:   }
498: 
499:   if (matches.length === 0) {
500:     return outcome(referencePath, 'fixture', submitted, 'unresolved', { reason: missingReason });
501:   }
502: 
503:   // `fixture.source_ref` is unique, so more than one match is not reachable
504:   // through the present schema. The branch is kept so that relaxing that
505:   // constraint stages the reference rather than silently taking the first row.
506:   if (matches.length > 1) {
507:     return outcome(referencePath, 'fixture', submitted, 'ambiguous', {
