544:       reason:
545:         'The fixture source identifier resolved, but the supplied fixture-team metadata could not be resolved, so it cannot be checked against the canonical fixture.',
546:     });
547:   }
548: 
549:   const metadataConflicts: string[] = [];
550: 
551:   if (context && match.startDate !== context.date) {
552:     metadataConflicts.push(
553:       `date (submitted ${context.date}, canonical ${match.startDate ?? 'unknown'})`,
554:     );
555:   }
556: 
557:   if (seasonName !== null && match.season !== seasonName) {
558:     metadataConflicts.push(
559:       `season (submitted ${seasonName}, canonical ${match.season ?? 'unknown'})`,
560:     );
561:   }
562: 
563:   if (context) {
564:     const submittedTeamIds = teamOutcomes.map((value) => value.canonicalId as string).sort();
