566: 
567:     const teamsMatch =
568:       submittedTeamIds.length === canonicalTeamIds.length &&
569:       submittedTeamIds.every((teamId, index) => teamId === canonicalTeamIds[index]);
570: 
571:     if (!teamsMatch) {
572:       metadataConflicts.push('team pair');
573:     }
574: 
575:     if (context.venue !== undefined && context.venue !== match.venue) {
576:       metadataConflicts.push(
577:         `venue (submitted ${context.venue}, canonical ${match.venue ?? 'unknown'})`,
578:       );
579:     }
580:   }
581: 
582:   if (metadataConflicts.length > 0) {
583:     return outcome(referencePath, 'fixture', submitted, 'invalid', {
