585:         {
586:           canonicalId: match.canonicalId,
587:           label: fixtureLabel(match.startDate, match.season),
588:         },
589:       ],
590:       reason:
591:         'FIXTURE_METADATA_CONFLICT: The fixture source identifier resolves to canonical data that disagrees with the submitted ' +
