781: function resolveParticipant(
782:   referencePath: string,
783:   reference: ReferenceInput,
784:   fixtureOutcome: ReferenceOutcome,
785:   squadBySourceRef: Map<string, SquadMemberRow[]>,
786:   squadByCanonicalId: Map<string, SquadMemberRow[]>,
787:   squadByDisplayName: Map<string, SquadMemberRow[]>,
788:   squadByAlias: Map<string, SquadAliasRow[]>,
789: ): ReferenceOutcome {
790:   const submitted = { sourceId: reference.sourceId, context: reference.context };
791: 
792:   if (fixtureOutcome.state !== 'resolved') {
793:     return outcome(referencePath, 'participant', submitted, 'unresolved', {
794:       reason:
795:         'The fixture reference did not resolve, so no squad scope is available. A participant name is never matched globally.',
796:     });
797:   }
798: 
799:   if (reference.sourceId) {
800:     const identifier = parseSourceIdentifier(reference.sourceId);
801: 
802:     if (!identifier) {
803:       return outcome(referencePath, 'participant', submitted, 'invalid', {
804:         reason: 'The source identifier could not be read as namespace:entityType:value.',
805:       });
806:     }
807: 
808:     if (identifier.namespace === APPLICATION_SOURCE_NAMESPACE) {
809:       if (!/^[1-9]\d*$/.test(identifier.value)) {
810:         return outcome(referencePath, 'participant', submitted, 'invalid', {
811:           reason:
812:             'An application participant reference must contain a positive database identifier.',
813:         });
814:       }
815:       const matches = squadByCanonicalId.get(identifier.value) ?? [];
816:       if (matches.length === 1) {
817:         return outcome(referencePath, 'participant', submitted, 'resolved', {
818:           canonicalId: matches[0]!.canonicalId,
819:           matchedBy: 'application-id',
820:         });
821:       }
822:       return outcome(referencePath, 'participant', submitted, 'unresolved', {
823:         reason: `Participant "${identifier.value}" is not a member of the resolved fixture squad.`,
824:       });
825:     }
826: 
827:     if (identifier.namespace !== CANONICAL_SOURCE_NAMESPACE) {
828:       return outcome(referencePath, 'participant', submitted, 'unresolved', {
829:         reason: `Source identifiers are compared only within the "${CANONICAL_SOURCE_NAMESPACE}" or "${APPLICATION_SOURCE_NAMESPACE}" namespaces; this reference names "${identifier.namespace}".`,
830:       });
831:     }
832: 
833:     const matches = squadBySourceRef.get(identifier.value) ?? [];
834: 
835:     if (matches.length === 1) {
836:       return outcome(referencePath, 'participant', submitted, 'resolved', {
837:         canonicalId: matches[0]!.canonicalId,
838:         matchedBy: 'source-identifier',
839:       });
840:     }
841: 
842:     return outcome(referencePath, 'participant', submitted, 'unresolved', {
843:       reason: `No member of the resolved fixture squad carries the source reference "${identifier.value}".`,
844:     });
845:   }
846: 
847:   const name = readableName(reference);
848: 
849:   if (!name) {
850:     return outcome(referencePath, 'participant', submitted, 'invalid', {
851:       reason: 'The participant reference carries neither a source identifier nor a readable name.',
852:     });
853:   }
854: 
855:   const byDisplayName = squadByDisplayName.get(name) ?? [];
856: 
857:   if (byDisplayName.length === 1) {
858:     return outcome(referencePath, 'participant', submitted, 'resolved', {
859:       canonicalId: byDisplayName[0]!.canonicalId,
860:       matchedBy: 'exact-name',
861:     });
862:   }
863: 
864:   if (byDisplayName.length > 1) {
865:     return outcome(referencePath, 'participant', submitted, 'ambiguous', {
866:       candidates: byDisplayName.map((member) => ({
867:         canonicalId: member.canonicalId,
868:         label: member.displayName,
869:       })),
870:       reason: `The name "${name}" belongs to ${String(byDisplayName.length)} members of this fixture squad.`,
871:     });
872:   }
873: 
874:   // A participant renamed since the fixture was recorded is matched on a unique
875:   // exact alias within the resolved fixture, and the alias match is recorded.
876:   const distinctAliasPeople = distinct(
877:     (squadByAlias.get(name) ?? []).map((alias) => alias.canonicalId),
878:   );
879: 
880:   if (distinctAliasPeople.length === 1) {
881:     return outcome(referencePath, 'participant', submitted, 'resolved', {
882:       canonicalId: distinctAliasPeople[0]!,
883:       matchedBy: 'exact-alias',
884:     });
885:   }
886: 
887:   if (distinctAliasPeople.length > 1) {
888:     return outcome(referencePath, 'participant', submitted, 'ambiguous', {
889:       candidates: distinctAliasPeople.map((canonicalId) => ({ canonicalId, label: name })),
890:       reason: `The alias "${name}" belongs to ${String(distinctAliasPeople.length)} members of this fixture squad.`,
891:     });
892:   }
893: 
894:   return outcome(referencePath, 'participant', submitted, 'unresolved', {
895:     reason: `No member of the resolved fixture squad is named "${name}", under that name or any recorded alias.`,
896:   });
897: }
