603: function resolveFixtureByNaturalKey(
604:   referencePath: string,
605:   submitted: unknown,
606:   context: { date: string },
607:   teamOutcomes: ReferenceOutcome[],
608:   candidateRows: FixtureByNaturalKeyRow[],
609:   seasonName: string | null,
610:   ignoredNote: string | null = null,
611: ): ReferenceOutcome {
612:   if (teamOutcomes.some((value) => value.state !== 'resolved')) {
613:     return outcome(referencePath, 'fixture', submitted, 'unresolved', {
614:       reason: withNote(
615:         ignoredNote,
616:         'The fixture natural key is expressed in terms of its teams, and at least one team reference did not resolve.',
617:       ),
618:     });
619:   }
620: 
621:   const teamIds = teamOutcomes.map((value) => value.canonicalId as string).sort();
622: 
623:   const matches = candidateRows.filter((row) => {
624:     if (row.startDate !== context.date) {
625:       return false;
626:     }
627: 
628:     // The season narrows the key when the package supplies one. A mismatch
629:     // stages the fixture rather than being quietly ignored.
630:     if (seasonName !== null && row.season !== seasonName) {
631:       return false;
632:     }
633: 
634:     const rowTeamIds = row.teamIds.slice().sort();
635:     return (
636:       rowTeamIds.length === teamIds.length &&
637:       rowTeamIds.every((teamId, index) => teamId === teamIds[index])
638:     );
639:   });
640: 
641:   if (matches.length === 1) {
642:     return outcome(referencePath, 'fixture', submitted, 'resolved', {
643:       canonicalId: matches[0]!.canonicalId,
644:       matchedBy: 'natural-key',
645:       reason: ignoredNote,
646:     });
647:   }
648: 
649:   // Measured over the corpus, 131 of 13,880 natural keys identify two fixtures,
650:   // so this is a real outcome rather than a defensive branch.
651:   if (matches.length > 1) {
652:     return outcome(referencePath, 'fixture', submitted, 'ambiguous', {
653:       candidates: matches.map((row) => ({
654:         canonicalId: row.canonicalId,
655:         label: fixtureLabel(row.startDate, row.season),
656:       })),
657:       reason: withNote(
658:         ignoredNote,
659:         `The competition, season, date and teams identify ${String(matches.length)} fixtures.`,
660:       ),
661:     });
662:   }
663: 
664:   return outcome(referencePath, 'fixture', submitted, 'unresolved', {
665:     reason: withNote(
666:       ignoredNote,
667:       'No fixture in the declared competition matches this date, season and pair of teams. A new fixture is a review decision, not a resolution.',
668:     ),
669:   });
670: }
