672: function resolveInnings(
673:   referencePath: string,
674:   submitted: unknown,
675:   sourceId: string | undefined,
676:   context: { ordinal: number } | null,
677:   fixtureOutcome: ReferenceOutcome,
678:   inningsRows: InningsRow[],
679:   battingTeamOutcome: ReferenceOutcome | null,
680: ): ReferenceOutcome {
681:   if (fixtureOutcome.state !== 'resolved') {
682:     return outcome(referencePath, 'innings', submitted, 'unresolved', {
683:       reason:
684:         'The fixture reference did not resolve, so no innings scope is available. An innings is never matched outside its fixture.',
685:     });
686:   }
687: 
688:   const inningsKey = 'the innings ordinal and batting team';
689:   let matches: InningsRow[];
690:   let matchedBy: ReferenceMatchMethod;
691:   let note: string | null = null;
692: 
693:   if (sourceId) {
694:     const identifier = parseSourceIdentifier(sourceId);
695:     if (!identifier) {
696:       return outcome(referencePath, 'innings', submitted, 'invalid', {
697:         reason: 'The source identifier could not be read as namespace:entityType:value.',
698:       });
699:     }
700: 
701:     if (identifier.namespace === APPLICATION_SOURCE_NAMESPACE) {
702:       if (!/^[1-9]\d*$/.test(identifier.value)) {
703:         return outcome(referencePath, 'innings', submitted, 'invalid', {
704:           reason: 'An application innings reference must contain a positive database identifier.',
705:         });
706:       }
707:       matches = inningsRows.filter((row) => row.canonicalId === identifier.value);
708:       matchedBy = 'application-id';
709:     } else {
710:       if (!context) {
711:         return outcome(referencePath, 'innings', submitted, 'unresolved', {
712:           reason: unsupportedSourceIdentifier('innings', inningsKey),
713:         });
714:       }
715:       matches = inningsRows.filter((row) => row.ordinal === context.ordinal);
716:       matchedBy = 'ordinal';
717:       note = ignoredSourceIdentifier('innings', inningsKey);
718:     }
719:   } else if (context) {
720:     matches = inningsRows.filter((row) => row.ordinal === context.ordinal);
721:     matchedBy = 'ordinal';
722:   } else {
723:     return outcome(referencePath, 'innings', submitted, 'invalid', {
724:       reason: 'The innings reference carries neither a source identifier nor readable context.',
725:     });
726:   }
727: 
728:   if (matches.length === 0) {
729:     return outcome(referencePath, 'innings', submitted, 'unresolved', {
730:       reason: sourceId?.startsWith(`${APPLICATION_SOURCE_NAMESPACE}:`)
731:         ? 'The application innings identifier does not belong to the resolved fixture.'
732:         : withNote(
733:             note,
734:             `The resolved fixture has no innings with ordinal ${String(context?.ordinal)}.`,
735:           ),
736:     });
737:   }
738: 
739:   if (matches.length > 1) {
740:     return outcome(referencePath, 'innings', submitted, 'ambiguous', {
741:       candidates: matches.map((row) => ({
742:         canonicalId: row.canonicalId,
743:         label: `innings ${String(row.ordinal)}`,
744:       })),
745:       reason: withNote(note, 'More than one innings matched within the resolved fixture.'),
746:     });
747:   }
748: 
749:   const match = matches[0]!;
750: 
751:   if (context && match.ordinal !== context.ordinal) {
752:     return outcome(referencePath, 'innings', submitted, 'invalid', {
753:       candidates: [{ canonicalId: match.canonicalId, label: `innings ${String(match.ordinal)}` }],
754:       reason:
755:         'The application innings identifier resolves to a different ordinal from the submitted context.',
756:     });
757:   }
758: 
759:   if (
760:     battingTeamOutcome &&
761:     battingTeamOutcome.state === 'resolved' &&
762:     match.battingTeamId !== null &&
763:     match.battingTeamId !== battingTeamOutcome.canonicalId
764:   ) {
765:     return outcome(referencePath, 'innings', submitted, 'invalid', {
766:       candidates: [{ canonicalId: match.canonicalId, label: `innings ${String(match.ordinal)}` }],
767:       reason: withNote(
768:         note,
769:         'The innings records a different batting team from the one submitted.',
770:       ),
771:     });
772:   }
773: 
774:   return outcome(referencePath, 'innings', submitted, 'resolved', {
775:     canonicalId: match.canonicalId,
776:     matchedBy,
777:     reason: note,
778:   });
779: }
