      team: 'SELECT count(*)::text AS count FROM team WHERE starts_with(name, $1)',
      person: `
        SELECT count(*)::text AS count
        FROM person
        WHERE starts_with(display_name, $1) OR starts_with(source_ref, $1)
      `,
