116:        SELECT source.innings_id, marker."from", marker."to", marker.type, $1::bigint
117:        FROM source
118:        CROSS JOIN LATERAL jsonb_to_recordset(source.powerplays) AS marker(
119:          "from" numeric(5,2), "to" numeric(5,2), type text
120:        )
